0KV GONDANGWETAN #1","id":"MTU-BAY-UPT-PBG-GI-150KV-PIER-PHT-150KV-GONDANGWETAN-1"}]},{"uptId":"UPT-PBG","ultgName":"PROBOLINGGO","name":"GI 150KV PROBOLINGGO","id":"MTU-GI-UPT-PBG-GI-150KV-PROBOLINGGO","bays":[{"name":"PHT 150KV LUMAJANG #2","id":"MTU-BAY-UPT-PBG-GI-150KV-PROBOLINGGO-PHT-150KV-LUMAJANG-2"},{"name":"TRF#3 150/20KV","id":"MTU-BAY-UPT-PBG-GI-150KV-PROBOLINGGO-TRF-3-150-20KV"}]},{"uptId":"UPT-PBG","ultgName":"BANGIL","name":"GI 150KV REJOSO","id":"MTU-GI-UPT-PBG-GI-150KV-REJOSO","bays":[{"name":"PHT 150KV GONDANGWETAN #1","id":"MTU-BAY-UPT-PBG-GI-150KV-REJOSO-PHT-150KV-GONDANGWETAN-1"}]},{"uptId":"UPT-PBG","ultgName":"JEMBER","name":"GI 150KV SITUBONDO","id":"MTU-GI-UPT-PBG-GI-150KV-SITUBONDO","bays":[{"name":"KOPEL BUS 150KV","id":"MTU-BAY-UPT-PBG-GI-150KV-SITUBONDO-KOPEL-BUS-150KV"}]},{"uptId":"UPT-PBG","ultgName":"JEMBER","name":"GI 150KV TANGGUL","id":"MTU-GI-UPT-PBG-GI-150KV-TANGGUL","bays":[{"name":"PHT 150KV JEMBER #2","id":"MTU-BAY-UPT-PBG-GI-150KV-TANGGUL-PHT-150KV-JEMBER-2"}]},{"uptId":"UPT-PBG","ultgName":"PROBOLINGGO","name":"GISTET 500KV PAITON","id":"MTU-GI-UPT-PBG-GISTET-500KV-PAITON","bays":[{"name":"MTR#6 500KV (JAVA POWER)","id":"MTU-BAY-UPT-PBG-GISTET-500KV-PAITON-MTR-6-500KV-JAVA-POWER"}]},{"uptId":"UPT-PBG","ultgName":"PROBOLINGGO","name":"GITET 500KV GRATI","id":"MTU-GI-UPT-PBG-GITET-500KV-GRATI","bays":[{"name":"7B2 DIAMETER#2 500KV","id":"MTU-BAY-UPT-PBG-GITET-500KV-GRATI-7B2-DIAMETER-2-500KV"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA UTARA","name":"GI 150KV KENJERAN","id":"MTU-GI-UPT-SBY-GI-150KV-KENJERAN","bays":[{"name":"BUSBAR A","id":"MTU-BAY-UPT-SBY-GI-150KV-KENJERAN-BUSBAR-A"},{"name":"BUSBAR B","id":"MTU-BAY-UPT-SBY-GI-150KV-KENJERAN-BUSBAR-B"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA UTARA","name":"GI 150KV PERAK","id":"MTU-GI-UPT-SBY-GI-150KV-PERAK","bays":[{"name":"BUSBAR","id":"MTU-BAY-UPT-SBY-GI-150KV-PERAK-BUSBAR"},{"name":"PHT 150KV UJUNG","id":"MTU-BAY-UPT-SBY-GI-150KV-PERAK-PHT-150KV-UJUNG"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA SELATAN","name":"GI 150KV RUNGKUT","id":"MTU-GI-UPT-SBY-GI-150KV-RUNGKUT","bays":[{"name":"TRF#3 150/20KV","id":"MTU-BAY-UPT-SBY-GI-150KV-RUNGKUT-TRF-3-150-20KV"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA SELATAN","name":"GI 150KV SIDOARJO","id":"MTU-GI-UPT-SBY-GI-150KV-SIDOARJO","bays":[{"name":"TRF#2 150/20KV (INC)","id":"MTU-BAY-UPT-SBY-GI-150KV-SIDOARJO-TRF-2-150-20KV-INC"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA UTARA","name":"GI 150KV SUKOLILO","id":"MTU-GI-UPT-SBY-GI-150KV-SUKOLILO","bays":[{"name":"PHT 150KV KENJERAN # 1","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-KENJERAN-1"},{"name":"PHT 150KV KENJERAN # 2","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-KENJERAN-2"},{"name":"PHT 150KV NGAGEL #2","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-NGAGEL-2"},{"name":"PHT 150KV RUNGKUT # 1","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-RUNGKUT-1"},{"name":"PHT 150KV RUNGKUT # 2","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-RUNGKUT-2"},{"name":"PHT 150KV WONOKROMO # 1","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-PHT-150KV-WONOKROMO-1"},{"name":"TRF#1 150/20KV","id":"MTU-BAY-UPT-SBY-GI-150KV-SUKOLILO-TRF-1-150-20KV"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA SELATAN","name":"GI 70KV BUDURAN","id":"MTU-GI-UPT-SBY-GI-70KV-BUDURAN","bays":[{"name":"PHT 70KV MASPION # 1","id":"MTU-BAY-UPT-SBY-GI-70KV-BUDURAN-PHT-70KV-MASPION-1"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA SELATAN","name":"GIS 150KV BUDURAN","id":"MTU-GI-UPT-SBY-GIS-150KV-BUDURAN","bays":[{"name":"TRAFO 6","id":"MTU-BAY-UPT-SBY-GIS-150KV-BUDURAN-TRAFO-6"},{"name":"TRF#4 150/20KV","id":"MTU-BAY-UPT-SBY-GIS-150KV-BUDURAN-TRF-4-150-20KV"},{"name":"TRF#6 150/20KV","id":"MTU-BAY-UPT-SBY-GIS-150KV-BUDURAN-TRF-6-150-20KV"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA UTARA","name":"GIS 150KV SAWAHAN","id":"MTU-GI-UPT-SBY-GIS-150KV-SAWAHAN","bays":[{"name":"TRAFO 1","id":"MTU-BAY-UPT-SBY-GIS-150KV-SAWAHAN-TRAFO-1"},{"name":"TRF#1 150/20KV","id":"MTU-BAY-UPT-SBY-GIS-150KV-SAWAHAN-TRF-1-150-20KV"}]},{"uptId":"UPT-SBY","ultgName":"SURABAYA SELATAN","name":"GIS 150KV WARU","id":"MTU-GI-UPT-SBY-GIS-150KV-WARU","bays":[{"name":"TRF#6 150/20KV (INC)","id":"MTU-BAY-UPT-SBY-GIS-150KV-WARU-TRF-6-150-20KV-INC"},{"name":"TRF#7 150/20KV (INC)","id":"MTU-BAY-UPT-SBY-GIS-150KV-WARU-TRF-7-150-20KV-INC"}]}]$mtu_data$::jsonb)
  loop
    target_upt := item->>'uptId';
    target_name := item->>'name';

    if not exists (select 1 from public.upt where id = target_upt) then
      raise exception 'MTU_SEED_UPT_NOT_FOUND:%', target_upt;
    end if;

    select u.id
    into target_ultg
    from public.ultg u
    where u.upt_id = target_upt
      and regexp_replace(
        upper(regexp_replace(btrim(coalesce(u.data->>'nama', u.data->>'name', u.id)), '\s+', ' ', 'g')),
        '^ULTG\s+',
        '',
        'i'
      ) = item->>'ultgName'
    order by u.id
    limit 1;

    if target_ultg is null then
      target_ultg := 'MTU-ULTG-' || target_upt || '-' || regexp_replace(item->>'ultgName', '[^A-Z0-9]+', '-', 'g');
      insert into public.ultg(id, upt_id, data, created_at)
      values (
        target_ultg,
        target_upt,
        jsonb_build_object(
          'nama', 'ULTG ' || (item->>'ultgName'),
          'kode', 'ULTG-' || regexp_replace(item->>'ultgName', '[^A-Z0-9]+', '-', 'g'),
          'normalizedName', item->>'ultgName',
          'source', 'MTU_KHS_MASTER_SEED',
          'sourceSheet', 'Lapor UPT DISESUSAIKAN'
        ),
        extract(epoch from now())::bigint
      )
      on conflict (id) do nothing;

      select u.id
      into target_ultg
      from public.ultg u
      where u.id = target_ultg
        and u.upt_id = target_upt;
    end if;

    select gi.id
    into target_gi
    from public.mtu_khs_gardu_induk gi
    where gi.upt_id = target_upt
      and gi.normalized_name = target_name
    order by gi.id
    limit 1;

    if target_gi is null then
      target_gi := item->>'id';
      insert into public.mtu_khs_gardu_induk(
        id, upt_id, ultg_id, normalized_name, data, created_by
      )
      values (
        target_gi,
        target_upt,
        target_ultg,
        target_name,
        jsonb_build_object(
          'nama', target_name,
          'normalizedName', target_name,
          'source', 'MTU_KHS_MASTER_SEED',
          'sourceSheet', 'Lapor UPT DISESUSAIKAN',
          'sourceUrl', 'https://docs.google.com/spreadsheets/d/1P4uzA61kt5-B8SejwifQqQAmziDY5E3kPAKcXAFBI7g/edit#gid=2023228375'
        ),
        null
      )
      on conflict (id) do nothing;

      select gi.id
      into target_gi
      from public.mtu_khs_gardu_induk gi
      where gi.upt_id = target_upt
        and gi.normalized_name = target_name
      order by gi.id
      limit 1;
    end if;

    for bay_item in
      select value
      from jsonb_array_elements(item->'bays')
    loop
      if not exists (
        select 1
        from public.mtu_khs_gardu_induk_bay bay
        where bay.gardu_induk_id = target_gi
          and bay.normalized_name = bay_item->>'name'
      ) then
        insert into public.mtu_khs_gardu_induk_bay(
          id, gardu_induk_id, normalized_name, data, created_by
        )
        values (
          bay_item->>'id',
          target_gi,
          bay_item->>'name',
          jsonb_build_object(
            'nama', bay_item->>'name',
            'normalizedName', bay_item->>'name',
            'source', 'MTU_KHS_MASTER_SEED',
            'sourceSheet', 'Lapor UPT DISESUSAIKAN',
            'sourceUrl', 'https://docs.google.com/spreadsheets/d/1P4uzA61kt5-B8SejwifQqQAmziDY5E3kPAKcXAFBI7g/edit#gid=2023228375'
          ),
          null
        )
        on conflict (id) do nothing;
      end if;
    end loop;
  end loop;
end
$mtu_seed$;
